using System;
using System.IO;
using Newtonsoft.Json.Linq;

public class CPHInline
{
    public bool Execute()
    {
        string userId = args["userId"].ToString();
        string userName = args["userName"].ToString();

        // Load user data
        string dataPath = @"C:\StreamerBot\UserData\eggs.json";

        if (!File.Exists(dataPath)) {
            CPH.SendMessage($"@{userName}, no adventure data found!");
            return false;
        }

        string jsonData = File.ReadAllText(dataPath);
        JObject data = JObject.Parse(jsonData);

        // Check for active adventure
        if (data["activeAdventures"] == null || data["activeAdventures"][userId] == null) {
            CPH.SendMessage($"@{userName}, you don't have an active adventure! Use !adventure to start one.");
            return false;
        }

        JToken adventure = data["activeAdventures"][userId];

        // Check if adventure has expired (10 minutes)
        DateTime timestamp = DateTime.Parse(adventure["timestamp"].ToString());
        if ((DateTime.UtcNow - timestamp).TotalMinutes > 10) {
            data["activeAdventures"][userId] = null;
            File.WriteAllText(dataPath, data.ToString());
            CPH.SendMessage($"@{userName}, your adventure has expired! Use !adventure to start a new one.");
            return false;
        }

        // Get adventure details
        string adventureId = adventure["adventureId"].ToString();
        string challenge = adventure["challenge"].ToString();
        int dc = (int)adventure["dc"];
        string successOutcome = adventure["successOutcome"].ToString();
        string failureOutcome = adventure["failureOutcome"].ToString();
        int successReward = (int)adventure["successReward"];
        int failureReward = (int)adventure["failureReward"];

        // Calculate modifier
        int totalAdventures = (int)(data["users"][userId]["totalAdventures"] ?? 0);
        int modifier = Math.Min(totalAdventures / 10, 3); // +1 per 10 adventures, max +3

        // Roll D20
        Random rnd = new Random();
        int roll = rnd.Next(1, 21);
        int total = roll + modifier;

        bool success = total >= dc;
        bool critSuccess = roll == 20;
        bool critFail = roll == 1;

        // Determine outcome
        string outcome;
        int eggReward;
        int tokenBonus = 0;

        if (critSuccess) {
            outcome = successOutcome;
            eggReward = 300;
            tokenBonus = 1;
        } else if (critFail) {
            outcome = failureOutcome + " (Critical Failure!)";
            eggReward = -50;
        } else if (success) {
            outcome = successOutcome;
            eggReward = successReward;
        } else {
            outcome = failureOutcome;
            eggReward = failureReward;
        }

        // Update user data
        int currentEggs = (int)(data["users"][userId]["eggs"] ?? 0);
        int newEggs = Math.Max(0, currentEggs + eggReward);
        data["users"][userId]["eggs"] = newEggs;

        if (tokenBonus > 0) {
            int currentTokens = (int)(data["users"][userId]["d20Tokens"] ?? 0);
            data["users"][userId]["d20Tokens"] = currentTokens + tokenBonus;
        }

        // Update adventure stats
        data["users"][userId]["adventureState"] = adventureId;
        data["users"][userId]["lastAdventure"] = DateTime.UtcNow.ToString("o");
        data["users"][userId]["totalAdventures"] = totalAdventures + 1;

        // Clear active adventure
        data["activeAdventures"][userId] = null;

        File.WriteAllText(dataPath, data.ToString());

        // Build response
        string resultEmoji = success ? "✅" : "❌";
        if (critSuccess) resultEmoji = "💎";
        if (critFail) resultEmoji = "💀";

        string message = $"🎲 @{userName} rolls {challenge} saving throw:\n";
        message += $"Rolled: {roll}";
        if (modifier > 0) message += $" + {modifier} modifier";
        message += $" = {total} vs DC {dc}\n";
        message += $"{resultEmoji} ";

        if (critSuccess) {
            message += "CRITICAL SUCCESS!\n";
        } else if (critFail) {
            message += "CRITICAL FAILURE!\n";
        } else if (success) {
            message += "Success!\n";
        } else {
            message += "Failure!\n";
        }

        message += $"📖 {outcome}\n";

        if (eggReward >= 0) {
            message += $"🎁 Reward: +{eggReward} eggs!";
        } else {
            message += $"💸 Lost: {Math.Abs(eggReward)} eggs";
        }

        if (tokenBonus > 0) {
            message += $" +{tokenBonus} D20 Token!";
        }

        message += $"\n🥚 Total Eggs: {newEggs}";
        message += $"\n📚 Your adventure continues... Use !adventure again tomorrow!";

        CPH.SendMessage(message);

        return true;
    }
}
